struct Db{sqlite3* p=nullptr;explicit Db(const fs::path& f){check(sqlite3_open_v2(f.u8string().c_str(),&p,SQLITE_OPEN_READWRITE,nullptr)==SQLITE_OK,"fixture open");S::exec(p,"PRAGMA foreign_keys=ON");}~Db(){sqlite3_close(p);}};
